UPDATE t_session_stats
SET message_count = message_count + 1
WHERE session_id = #{sessionId}

UPDATE t_session_stats
SET cached_tokens = cached_tokens + #{cachedTokens},
    uncached_tokens = uncached_tokens + #{uncachedTokens},
    total_tokens = total_tokens + #{totalTokens},
    cost_total = cost_total + #{costTotal}
WHERE session_id = #{sessionId}

UPDATE t_sessions
SET active_leaf_id = #{activeLeafId}
WHERE id = #{sessionId}
  AND state = 'running'

